package main

import (
	"github.com/Dzarlax-AI/evening-news/go-tools/runtimeconfig"
	"os"
)

func configLookup() (func(string) string, error) {
	path, present := os.LookupEnv("NEWS_RUNTIME_FILE")
	if !present {
		return os.Getenv, nil
	}
	allowed := []string{"ARTICLE_AI_TOKEN", "ARTICLE_AI_URL", "ARTICLE_INGESTION_DB_MAX_CONNS", "ARTICLE_INGESTION_LISTEN", "ARTICLE_INGESTION_TOKEN", "ARTICLE_PROCESSING_DB_MAX_CONNS", "ARTICLE_PROCESSING_LISTEN", "ARTICLE_PROCESSING_TOKEN", "BACKGROUND_HEALTH_LISTEN", "BACKGROUND_SHUTDOWN_TIMEOUT_SECONDS", "BACKGROUND_WORKER_BACKOFF_MAX", "BACKGROUND_WORKER_BACKOFF_MIN", "DOMAIN_SERVICE_URL", "EXECUTION_DATABASE_URL", "EXECUTION_DB_SCHEMA", "EXECUTION_MAX_CONNECTIONS", "EXTRACTION_BROWSER_MAX_BYTES", "EXTRACTION_HTTP_MAX_BYTES", "EXTRACTION_SERVICE_NATIVE_BROWSER", "EXTRACTION_SERVICE_TIMEOUT_SECONDS", "EXTRACTION_SERVICE_TOKEN", "EXTRACTION_SERVICE_TOTAL_BUDGET_SECONDS", "EXTRACTION_SERVICE_URL", "EXTRACTION_TEXT_MAX_CHARS", "INGESTION_DATABASE_URL", "JOB_EXECUTOR_LISTEN", "JOB_EXECUTOR_REQUEST_TIMEOUT_SECONDS", "JOB_EXECUTOR_TOKEN", "JOB_EXECUTOR_URL", "MAX_WORKERS", "NEWS_LIMIT_DAYS", "NEWS_LIMIT_ENABLED", "NEWS_LIMIT_MAX_ARTICLES", "NEWS_LIMIT_NEWEST_DATE", "NEWS_LIMIT_PER_SOURCE", "PROCESSING_ATTEMPT_TIMEOUT_SECONDS", "PROCESSING_BATCH_SIZE", "PROCESSING_DATABASE_URL", "PROCESSING_MAX_ATTEMPTS", "PROCESSING_RETRY_INITIAL_SECONDS", "PROCESSING_RETRY_LATER_SECONDS", "SCHEDULER_ALLOW_HTTP_TARGETS", "SCHEDULER_API_TOKEN", "SCHEDULER_DATABASE_URL", "SCHEDULER_DB_MAX_CONNS", "SCHEDULER_DB_SCHEMA", "SCHEDULER_HTTP_TIMEOUT", "SCHEDULER_LISTEN_ADDR", "SCHEDULER_MAX_INFLIGHT", "SCHEDULER_MAX_OUTBOX", "SCHEDULER_POLL_INTERVAL", "SCHEDULER_START_PAUSED", "SCHEDULER_TARGET_ALIASES", "SCHEDULER_TARGET_NEWS_WORKER_URL", "SCHEDULER_TARGET_NEWS_WORKER_TOKEN", "SELECTOR_SERVICE_URL", "WORKER_DATABASE_URL", "WORKER_JOB_RETENTION_DAYS", "WORKER_MAX_JOB_ATTEMPTS", "WORKER_POLL_INTERVAL_SECONDS", "WORKER_SHUTDOWN_DRAIN_SECONDS"}
	required := []string{"WORKER_DATABASE_URL", "EXECUTION_DATABASE_URL", "INGESTION_DATABASE_URL", "PROCESSING_DATABASE_URL", "SCHEDULER_DATABASE_URL", "JOB_EXECUTOR_TOKEN", "ARTICLE_AI_TOKEN", "ARTICLE_INGESTION_TOKEN", "ARTICLE_PROCESSING_TOKEN", "SCHEDULER_API_TOKEN", "SCHEDULER_TARGET_NEWS_WORKER_TOKEN", "EXTRACTION_SERVICE_TOKEN"}
	m, err := runtimeconfig.Load(path, "background", allowed, required)
	if err != nil {
		return nil, err
	}
	return func(k string) string { return m.Values[k] }, nil
}
